import React, { useState, useRef, useEffect, useCallback } from 'react';

const ImagePositionSelector = ({ imageUrl, initialPosition, onChange }) => {
  const containerRef = useRef(null);
  const imageRef = useRef(null);
  const [isDragging, setIsDragging] = useState(false);
  const [position, setPosition] = useState({ x: 50, y: 50 }); // Default center position (50%, 50%)
  const [imageSize, setImageSize] = useState({ width: 0, height: 0 });
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Parse initial position into x, y percentages
  useEffect(() => {
    if (initialPosition) {
      // Handle both string format "x% y%" and named positions
      if (initialPosition.includes('%')) {
        const [x, y] = initialPosition.split(' ').map(val => 
          parseInt(val.replace('%', ''), 10)
        );
        if (!isNaN(x) && !isNaN(y)) {
          setPosition({ x, y });
        }
      } else {
        const positionMap = {
          'center': { x: 50, y: 50 },
          'top': { x: 50, y: 0 },
          'bottom': { x: 50, y: 100 },
          'left': { x: 0, y: 50 },
          'right': { x: 100, y: 50 },
          'top left': { x: 0, y: 0 },
          'top right': { x: 100, y: 0 },
          'bottom left': { x: 0, y: 100 },
          'bottom right': { x: 100, y: 100 }
        };
        
        setPosition(positionMap[initialPosition] || { x: 50, y: 50 });
      }
    }
  }, [initialPosition]);

  // Update container and image sizes on mount and resize
  useEffect(() => {
    const updateSizes = () => {
      if (containerRef.current && imageRef.current) {
        setContainerSize({
          width: containerRef.current.offsetWidth,
          height: containerRef.current.offsetHeight
        });
        
        // We need to get the natural dimensions of the image
        const img = new Image();
        img.src = imageUrl;
        img.onload = () => {
          setImageSize({
            width: img.naturalWidth,
            height: img.naturalHeight
          });
        };
      }
    };

    updateSizes();
    window.addEventListener('resize', updateSizes);
    
    return () => {
      window.removeEventListener('resize', updateSizes);
    };
  }, [imageUrl]);

  // Convert position to CSS background-position and notify parent
  useEffect(() => {
    const backgroundPosition = `${position.x}% ${position.y}%`;
    onChange(backgroundPosition);
  }, [position, onChange]);

  // Memoize the update position function to prevent recreating it on each render
  const updatePosition = useCallback((clientX, clientY) => {
    if (!containerRef.current) return;
    
    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(100, ((clientX - rect.left) / rect.width) * 100));
    const y = Math.max(0, Math.min(100, ((clientY - rect.top) / rect.height) * 100));
    
    setPosition({ x, y });
  }, []);

  const handleMouseDown = (e) => {
    e.preventDefault(); // Prevent text selection during drag
    setIsDragging(true);
    updatePosition(e.clientX, e.clientY);
    
    // Add event listeners to window to handle mouse movements outside the container
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);
  };

  const handleMouseMove = useCallback((e) => {
    if (isDragging) {
      e.preventDefault();
      updatePosition(e.clientX, e.clientY);
    }
  }, [isDragging, updatePosition]);

  const handleMouseUp = useCallback(() => {
    setIsDragging(false);
    
    // Remove event listeners when done dragging
    window.removeEventListener('mousemove', handleMouseMove);
    window.removeEventListener('mouseup', handleMouseUp);
  }, [handleMouseMove]);

  // Add and remove window event listeners
  useEffect(() => {
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  const handleTouchStart = (e) => {
    e.preventDefault();
    setIsDragging(true);
    if (e.touches && e.touches[0]) {
      updatePosition(e.touches[0].clientX, e.touches[0].clientY);
    }
    
    // Add event listeners to handle touch movements
    window.addEventListener('touchmove', handleTouchMove, { passive: false });
    window.addEventListener('touchend', handleTouchEnd);
  };

  const handleTouchMove = useCallback((e) => {
    if (isDragging && e.touches && e.touches[0]) {
      e.preventDefault();
      updatePosition(e.touches[0].clientX, e.touches[0].clientY);
    }
  }, [isDragging, updatePosition]);

  const handleTouchEnd = useCallback(() => {
    setIsDragging(false);
    
    // Remove event listeners when done dragging
    window.removeEventListener('touchmove', handleTouchMove);
    window.removeEventListener('touchend', handleTouchEnd);
  }, [handleTouchMove]);

  // Add and remove touch event listeners
  useEffect(() => {
    return () => {
      window.removeEventListener('touchmove', handleTouchMove);
      window.removeEventListener('touchend', handleTouchEnd);
    };
  }, [handleTouchMove, handleTouchEnd]);

  // Preset position buttons
  const presetPositions = [
    { name: 'Center', x: 50, y: 50 },
    { name: 'Top', x: 50, y: 0 },
    { name: 'Bottom', x: 50, y: 100 },
    { name: 'Left', x: 0, y: 50 },
    { name: 'Right', x: 100, y: 50 }
  ];

  return (
    <div className="image-position-selector">
      <div className="position-preview-container">
        <div 
          ref={containerRef}
          className="position-preview"
          style={{
            backgroundImage: `url(${imageUrl})`,
            backgroundPosition: `${position.x}% ${position.y}%`,
            backgroundSize: 'cover',
            cursor: isDragging ? 'grabbing' : 'grab'
          }}
          onMouseDown={handleMouseDown}
          onTouchStart={handleTouchStart}
        >
          <div 
            ref={imageRef}
            className="position-indicator"
            style={{
              left: `${position.x}%`,
              top: `${position.y}%`
            }}
          ></div>
          <div className="position-instructions">
            Drag to adjust image position
          </div>
        </div>
      </div>
      <div className="position-controls">
        <div className="position-presets">
          {presetPositions.map(preset => (
            <button 
              key={preset.name}
              type="button" 
              className="position-preset"
              onClick={() => setPosition({ x: preset.x, y: preset.y })}
            >
              {preset.name}
            </button>
          ))}
        </div>
        <div className="position-values">
          X: {Math.round(position.x)}%, Y: {Math.round(position.y)}%
        </div>
      </div>
    </div>
  );
};

export default ImagePositionSelector;
